import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { getDocument } from "pdfjs-dist/legacy/build/pdf.mjs";
import { parseWithMapping } from "@kys/statement";
import { attribute, DEFAULT_CONTEXT } from "../src/attribute";
import { pdfToStatementCsv, readPdfStatement, type PdfJsLike, type PdfPage } from "../src/pdf-statement";

// Mock statements with made-up people and numbers, generated by fixtures/make_pdfs.py.
const dir = new URL("./fixtures/", import.meta.url);
const truth = JSON.parse(readFileSync(new URL("truth.json", dir), "utf8")) as Record<string, { rows: number; out: number; in: number; first: string }> & {
  "revolut-multicurrency": { byCurrency: Record<string, { rows: number; out: number; in: number }> };
};
const read = (name: string) => {
  const bytes = readFileSync(new URL(`${name}.pdf`, dir));
  return readPdfStatement(pdfjs, bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength), parseWithMapping);
};
const pdfjs = { getDocument: (src) => getDocument({ ...src, useSystemFonts: true }) } as PdfJsLike;

describe("PDF statements", () => {
  for (const name of ["revolut", "monzo", "barclays", "revolut-2026"]) {
    it(`reads every row of a ${name}-style statement`, async () => {
      const bytes = readFileSync(new URL(`${name}.pdf`, dir));
      const { result, pdf } = await readPdfStatement(pdfjs, bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength), parseWithMapping);
      const t = truth[name]!;
      expect(pdf.rows).toBe(t.rows);
      expect(result.transactions).toHaveLength(t.rows);
      const out = result.transactions.filter((x) => x.amount < 0).reduce((s, x) => s - x.amount, 0);
      const inn = result.transactions.filter((x) => x.amount > 0).reduce((s, x) => s + x.amount, 0);
      expect(out).toBeCloseTo(t.out, 2);
      expect(inn).toBeCloseTo(t.in, 2);
      expect(result.bank).toMatchObject({ id: name.replace(/-.*/, "") });
      if (name !== "revolut-2026") expect(result.dateRange).toEqual({ from: "2026-07-01", to: "2026-07-30" });
    });
  }

  it("keeps Revolut's 'To:' line as the raw descriptor but drops card numbers and references", async () => {
    const bytes = readFileSync(new URL("revolut.pdf", dir));
    const { result, pdf } = await readPdfStatement(pdfjs, bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength), parseWithMapping);
    expect(pdf.csv).not.toMatch(/Card: |535522|Reference: /);
    const shop = result.transactions.find((x) => x.rawPayee === "Tesco");
    expect(shop?.rawDescription).toMatch(/^TESCO STORES 3456/);
    // the pending £9.99 Tesco payment is left out
    expect(result.transactions.some((x) => x.amount === -9.99)).toBe(false);
  });

  it("reads Revolut's 2026 layout: type codes, spaced thousands, FX lines, headings once, two periods", async () => {
    const bytes = readFileSync(new URL("revolut-2026.pdf", dir));
    const { result } = await readPdfStatement(pdfjs, bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength), parseWithMapping);
    const t = (p: string) => result.transactions.filter((x) => x.rawPayee === p);
    expect(t("Paypal *tcgplayer")[0]).toMatchObject({ amount: -2296.15, typeLabel: "CAR", kind: "spend" });
    // the $ amount under an FX line is not a transaction, and the " • reference" is stripped
    expect(result.transactions.some((x) => Math.abs(x.amount) === 63.29)).toBe(false);
    expect(t("Paypal Uk")[0]?.kind).toBe("internal");
    expect(result.transactions.every((x) => x.amount !== 0)).toBe(true);
    expect(result.dateRange?.to).toBe("2026-06-30");
  });

  it("reads first direct's layout: type codes, payments over several lines, cash and card payments abroad (18 Oct 2026)", async () => {
    const { result, pdf } = await read("firstdirect");
    const t = truth.firstdirect!;
    expect(pdf.rows).toBe(t.rows);
    const out = result.transactions.filter((x) => x.amount < 0).reduce((s, x) => s - x.amount, 0);
    const inn = result.transactions.filter((x) => x.amount > 0).reduce((s, x) => s + x.amount, 0);
    expect(out).toBeCloseTo(t.out, 2);
    expect(inn).toBeCloseTo(t.in, 2);
    // "MONZO* ME A FRIEND" on page 1 doesn't make it a Monzo statement
    expect(result.bank).toMatchObject({ id: "hsbc", name: "first direct" });
    expect(result.dateRange).toEqual({ from: "2026-07-10", to: "2026-07-15" });
    const by = (p: string) => result.transactions.find((x) => x.rawPayee === p)!;
    expect(by("TESCO STORES 3456")).toMatchObject({ amount: -23.45, typeLabel: "MAS", kind: "spend", rawDescription: "TESCO STORES 3456 LONDON" });
    expect(by("OCTOPUS ENERGY")).toMatchObject({ amount: -85, typeLabel: "DD", kind: "spend" });
    expect(by("ACME LTD SALARY")).toMatchObject({ amount: 1850, kind: "income", date: "2026-07-11" });
    // abroad: the INT'L reference and the exchange-rate lines go; the town stays, and what was charged goes last
    expect(by("WWW.EXAMPLETAXI.COM")).toMatchObject({ amount: -5.54, rawDescription: "WWW.EXAMPLETAXI.COM BANGKOK THB 250.00" });
    expect(by("NOODLE CORNER")).toMatchObject({ amount: -1.79, rawDescription: "NOODLE CORNER BANGKOK THB 80.00" });
    expect(by("EXAMPLE BANK")).toMatchObject({ amount: -44.49, typeLabel: "ATM", kind: "cash" });
    expect(pdf.csv).not.toMatch(/INT'L|CASH 00|MAS Rate|@ 4|Balance brought|Balance carried/);
    // the first payment on page 2 has no date: it's the last date on page 1, not the period line above the table
    expect(by("CAFE EXEMPLO")).toMatchObject({ date: "2026-07-12", amount: -5.56 });
    expect(by("J Smith").kind).toBe("transfer");
    expect(by("MONZO* ME A FRIEND").kind).toBe("transfer");
    expect(by("EXAMPLE OUTDOORS")).toMatchObject({ amount: 50, kind: "refund" });
    expect(by("Hotelnet HOTELNET 55").normPayee).toBe("HOTELNET");
    expect(attribute(by("WWW.EXAMPLETAXI.COM"), DEFAULT_CONTEXT)).toMatchObject({ basis: "estimated", country: "TH", evidence: "place", clue: "BANGKOK" });
  });

  it("reads a Revolut statement with a section per currency, and what card payments were charged in (18 Oct 2026)", async () => {
    const { result, pdf } = await read("revolut-multicurrency");
    const t = truth["revolut-multicurrency"].byCurrency;
    expect(result.bank).toMatchObject({ id: "revolut" });
    expect(pdf.currency).toBe("GBP");
    for (const ccy of ["EUR", "GBP", "USD"]) {
      const rows = result.transactions.filter((x) => x.currency === ccy);
      expect(rows, ccy).toHaveLength(t[ccy]!.rows);
      expect(rows.filter((x) => x.amount < 0).reduce((s, x) => s - x.amount, 0), ccy).toBeCloseTo(t[ccy]!.out, 2);
    }
    const by = (p: string) => result.transactions.find((x) => x.rawPayee === p)!;
    expect(by("Sp Example Games")).toMatchObject({ amount: -120, currency: "GBP", rawDescription: "Sp Example Games USD 160.80" });
    expect(attribute(by("Sp Example Games"), DEFAULT_CONTEXT)).toMatchObject({ basis: "estimated", country: "US", evidence: "currency" });
    // money sent keeps its "To" as printed (the payee is part of each payment's id, so re-imports still match)
    expect(by("To A Friend")).toMatchObject({ kind: "transfer", typeLabel: "MOS" });
    // the next section's "Balance summary" isn't a detail of the last payment before it
    expect(result.transactions.some((x) => /balance summary/i.test(x.rawDescription ?? ""))).toBe(false);
  });

  // Made-up pages built from positioned text, like pdf.js gives (x, y from the bottom of an A4 page).
  const cell = (str: string, x: number, y: number) => ({ str, x, y, w: str.length * 4.5, h: 8 });
  const page = (items: ReturnType<typeof cell>[]) => ({ width: 595, height: 842, items });

  it("reads the bank from what it prints about itself, not from a payee or the holder's name and address (18 Oct 2026)", () => {
    const revolut = pdfToStatementCsv([page([
      cell("Account statement", 360, 767), cell("John Wise", 42, 720), cell("12 Chase Road", 42, 710), cell("Halifax HX1 1AA", 42, 700),
      cell("Date", 43, 600), cell("Description", 172, 600), cell("Money out", 360, 600), cell("Money in", 443, 600), cell("Balance", 526, 600),
      cell("1 Jun 2026", 43, 580), cell("Tesco", 172, 580), cell("£10.00", 380, 580), cell("£90.00", 530, 580),
      cell("© 2026 Revolut Ltd", 36, 15),
    ])]);
    expect(revolut.bank).toEqual({ id: "revolut", name: "Revolut" });
    // a payee near the foot of the page is still in the table: a "Revolut Ltd" top-up doesn't make this Revolut's
    const barclays = pdfToStatementCsv([page([
      cell("Date", 40, 700), cell("Description", 110, 700), cell("Money out", 380, 700), cell("Money in", 460, 700), cell("Balance", 530, 700),
      cell("01/07/2026", 40, 680), cell("TESCO STORES 3456", 110, 680), cell("12.50", 400, 680), cell("987.50", 550, 680),
      cell("02/07/2026", 40, 52), cell("Revolut Ltd", 110, 52), cell("50.00", 400, 52), cell("937.50", 550, 52),
      cell("Barclays Bank UK PLC. Registered in England.", 40, 20),
    ])]);
    expect(barclays.bank).toEqual({ id: "barclays", name: "Barclays" });
    // a bank we don't list: a payee naming HSBC neither names the bank nor switches to HSBC's layout
    const unknown = pdfToStatementCsv([page([
      cell("Example Bank statement", 40, 780),
      cell("Date", 40, 700), cell("Description", 110, 700), cell("Money out", 380, 700), cell("Money in", 460, 700), cell("Balance", 530, 700),
      cell("01/07/2026", 40, 680), cell("Direct Debit to HSBC Credit Card", 110, 680), cell("50.00", 400, 680), cell("950.00", 550, 680),
      cell("02/07/2026", 40, 664), cell("TESCO STORES 3456", 110, 664), cell("12.50", 400, 664), cell("937.50", 550, 664),
      cell("03/07/2026", 40, 648), cell("ACME LTD SALARY", 110, 648), cell("1,000.00", 470, 648), cell("1,937.50", 550, 648),
      cell("04/07/2026", 40, 632), cell("NATIONWIDE BUILDING SOCIETY", 110, 632), cell("200.00", 400, 632), cell("1,737.50", 550, 632),
    ])]);
    expect(unknown.bank).toBeUndefined();
    expect(unknown.rows).toBe(4);
  });

  it("first direct: a shop called CASH… or INTL… is a shop, and a payment split by a page break carries on below the next heading (18 Oct 2026)", () => {
    const head = (y: number) => [cell("Date", 68, y), cell("Paym ent t ype and det ails", 131, y), cell("£ Paid out", 365, y), cell("£ Paid in", 453, y), cell("£ Balance", 528, y)];
    const r = pdfToStatementCsv([
      page([
        cell("firstdirect.com", 423, 775),
        ...head(593),
        cell("10 Jul 26", 68, 562), cell("MAS", 128, 562), cell("CASH CONVERTERS", 155, 562), cell("LEWISHAM", 155, 550), cell("20.00", 388, 550),
        cell("VIS", 128, 539), cell("INTL BOOKS", 155, 539), cell("LONDON", 155, 527), cell("8.00", 392, 527),
        cell("MAS", 128, 516), cell("CASH 4U", 155, 516), cell("LEWISHAM", 155, 504), cell("6.00", 392, 504),
        cell("DD", 128, 493), cell("SPLIT SHOP", 155, 493),
        cell("first direct is a division of HSBC UK Bank plc", 411, 14),
      ]),
      page([
        cell("Account Name", 68, 659), cell("Mx Alex Example", 68, 647), cell("12345678", 431, 647), cell("12", 512, 647),
        ...head(593),
        cell("A1B2C3D4", 155, 574), cell("7.00", 392, 574),
        cell("MAS", 128, 562), cell("NEXT PAGE SHOP", 155, 562), cell("LONDON", 155, 550), cell("5.00", 392, 550),
      ]),
    ]);
    const lines = r.csv.split("\n").slice(1);
    expect(lines.map((l) => l.split(",")[1])).toEqual(["CASH CONVERTERS", "INTL BOOKS", "CASH 4U", "SPLIT SHOP", "NEXT PAGE SHOP"]);
    expect(lines[0]).toMatch(/,MAS$/);
    expect(lines[3]).toBe("2026-07-10,SPLIT SHOP,SPLIT SHOP A1B2C3D4,7.00,,,GBP,DD");
    expect(r.csv).not.toMatch(/Account Name|Alex Example/);
  });

  it("says so when a PDF has no text (a scan)", () => {
    const pages: PdfPage[] = [{ items: [], width: 595, height: 842 }];
    const r = pdfToStatementCsv(pages);
    expect(r.noTable).toBe(true);
    expect(r.scanned).toBe(true);
    expect(r.warnings[0]).toMatch(/scan/);
  });

  it("reads a signed single amount column and dates with CR/DR markers", () => {
    const it = (str: string, x: number, y: number) => ({ str, x, y, w: str.length * 5, h: 9 });
    const pages: PdfPage[] = [{ width: 595, height: 842, items: [
      it("Date", 40, 800), it("Details", 110, 800), it("Amount", 400, 800), it("Balance", 500, 800),
      it("03/07/2026", 40, 780), it("TESCO STORES 3456", 110, 780), it("12.50 DR", 400, 780), it("100.00", 500, 780),
      it("04/07/2026", 40, 764), it("REFUND AMAZON", 110, 764), it("5.00 CR", 405, 764), it("105.00", 500, 764),
    ] }];
    const r = pdfToStatementCsv(pages);
    expect(r.rows).toBe(2);
    expect(r.csv.split("\n")[1]).toBe("2026-07-03,TESCO STORES 3456,TESCO STORES 3456,12.50,,100.00,GBP,");
    expect(r.csv.split("\n")[2]).toBe("2026-07-04,REFUND AMAZON,REFUND AMAZON,,5.00,105.00,GBP,");
  });
});
